import React from 'react';
import { ILineChart } from './interface';
/**
 * The Line Chart component displays a line chart using the AMCharts 5 library.
 * It visualizes data points over a continuous interval, allowing users to observe trends.
 *
 * ## Content
 *
 * The Line Chart component accepts a dataset containing x and y-axis values for plotting the line chart.
 * It provides options for customization, including styling, tooltips, and axis labels.
 *
 * ### Example Usage:
 *
 * ```tsx
 * import * as React from "react";
 * import Line from '@walmartluminate/chart-components';
 *
 * export default () => {
 *   const data = [
 *     { category: '10/11-10/24' , value1: 10 },
 *     { category: '6/25-7/08', value1: 15 },
 *   ];
 *   const chartConfig = [
 *     { value: 'value1', label: 'Internal Web Search'}
 *   ];
 *
 *   return <Line data={data} chartConfig={chartConfig} valueXAxis='category'/>;
 * };
 * ```
 *
 * ## Features
 *
 * - Line Chart Visualization: Displays data points with a line connecting them.
 * - Customization: Allows customization of various chart elements, such as colors and tooltips.
 * - Time Series Support: Supports date-based data for time series analysis.
 *
 * ## Variants
 *
 * The Line Chart component supports various chart variants:
 *
 * - Default: Standard line chart with default styling.
 * - Custom Styling: Allows customization of colors, line styles, and markers.
 * - Tooltip Interaction: Enables tooltips for data points on hover. set `isTooltip` to false to disable tooltip
 * - Color scheme: `colorScheme` accepts `mono` or `color` options to render lines with Walmart DV color theme or colors
 * - NumberFormat : numberFormat accepts currency or percent options to show the values dynamically in tooltip and Yaxis
 *
 * See code snippets in the documentation or library documentation for implementation details.
 */
export declare const LineChart: React.FC<ILineChart>;
